  1	/**
  2	 * El contrato de `migrationRunnerContract.ts`, aplicado a las dos
  3	 * implementaciones que `@thyrox/store` ofrece hoy: `runMigrationsSync`
  4	 * (sync, `bun:sqlite`) y `runMigrations` (async, `Bun.SQL`) sobre SQLite y,
  5	 * si `THYROX_TEST_POSTGRES_URL` está declarada, sobre PostgreSQL — misma
  6	 * forma de tres ramas que `contract.test.ts` ya usa para `sql.ts`.
  7	 */
  8	import { Database } from 'bun:sqlite'
  9	import { SQL } from 'bun'
 10	import { mkdtempSync, rmSync } from 'fs'
 11	import { tmpdir } from 'os'
 12	import { join } from 'path'
 13	import { describe, test } from 'bun:test'
 14	
 15	import { openByUrl } from '../sql.ts'
 16	import { runMigrations, type Migration as AsyncMigration } from '../migrations.ts'
 17	import { runMigrationsSync, type Migration as SyncMigration } from '../migrationsSync.ts'
 18	import { validateMigrationLedger, validateMigrationLedgerSync } from '../migrationLedger.ts'
 19	import { resolvePostgresTestUrl, withDisposableSchema } from '../testing/postgresTestSchema.ts'
 20	import { defineMigrationRunnerContract, type MigrationRunnerEngine } from './migrationRunnerContract.ts'
 21	
 22	/** El DDL heredado (sin `name`), portable entre sqlite y postgres. */
 23	const LEGACY_LEDGER_DDL = (table: string): string => `CREATE TABLE ${table} (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)`
 24	
 25	function syncSqliteEngine(db: Database): MigrationRunnerEngine {
 26	  return {
 27	    async run(options) {
 28	      return runMigrationsSync(db, options)
 29	    },
 30	    async tableExists(name) {
 31	      return db.query(`SELECT name FROM sqlite_master WHERE type='table' AND name = ?`).get(name) !== null
 32	    },
 33	    async controlColumns(table) {
 34	      return db.query(`PRAGMA table_info(${table})`).all() as { name: string; notnull: number; pk: number }[]
 35	    },
 36	    async controlVersions(table) {
 37	      return (db.query(`SELECT version FROM ${table} ORDER BY version`).all() as { version: number }[]).map(row => Number(row.version))
 38	    },
 39	    async controlNames(table) {
 40	      const rows = db.query(`SELECT version, name FROM ${table} ORDER BY version`).all() as { version: number; name: string }[]
 41	      return Object.fromEntries(rows.map(row => [Number(row.version), row.name]))
 42	    },
 43	    async seqLabels() {
 44	      return (db.query(`SELECT label FROM seq ORDER BY id`).all() as { label: string }[]).map(row => row.label)
 45	    },
 46	    async runWithAdoptionProbe({ table, probeVersion, probeName, probeTable }) {
 47	      const migrations: readonly SyncMigration[] = [
 48	        {
 49	          version: probeVersion,
 50	          name: probeName,
 51	          statements: { sqlite: [`CREATE TABLE ${probeTable} (id INTEGER PRIMARY KEY)`], postgres: [] },
 52	          alreadyApplied: probeDb => probeDb.query(`SELECT name FROM sqlite_master WHERE type='table' AND name = ?`).get(probeTable) !== null,
 53	        },
 54	      ]
 55	      return runMigrationsSync(db, { table, migrations })
 56	    },
 57	    async createTableDirectly(tableName) {
 58	      db.run(`CREATE TABLE ${tableName} (id INTEGER PRIMARY KEY)`)
 59	    },
 60	    async seedLegacyLedger(table, rows) {
 61	      db.run(LEGACY_LEDGER_DDL(table))
 62	      for (const row of rows) db.run(`INSERT INTO ${table} (version, applied_at) VALUES (?, ?)`, [row.version, row.appliedAt])
 63	    },
 64	    async validateLedger(options) {
 65	      validateMigrationLedgerSync(db, options)
 66	    },
 67	  }
 68	}
 69	
 70	function asyncEngine(sql: SQL, dialect: 'sqlite' | 'postgres'): MigrationRunnerEngine {
 71	  return {
 72	    async run(options) {
 73	      return runMigrations(sql, dialect, options)
 74	    },
 75	    async tableExists(name) {
 76	      if (dialect === 'postgres') {
 77	        const [row] = (await sql`SELECT to_regclass(${name}) IS NOT NULL AS found`) as { found: boolean }[]
 78	        return Boolean(row?.found)
 79	      }
 80	      const rows = (await sql.unsafe(`SELECT name FROM sqlite_master WHERE type='table' AND name = $1`, [name])) as { name: string }[]
 81	      return rows.length > 0
 82	    },
 83	    async controlColumns(table) {
 84	      if (dialect === 'postgres') {
 85	        // `information_schema.columns` no filtra por `search_path`: sin
 86	        // `table_schema = current_schema()` vería también las tablas
 87	        // homónimas de otro esquema de prueba desechable.
 88	        const rows = (await sql`
 89	          SELECT c.column_name AS name,
 90	                 (c.is_nullable = 'NO')::int AS notnull,
 91	                 (pk.column_name IS NOT NULL)::int AS pk
 92	          FROM information_schema.columns c
 93	          LEFT JOIN (
 94	            SELECT kcu.column_name
 95	            FROM information_schema.table_constraints tc
 96	            JOIN information_schema.key_column_usage kcu
 97	              ON kcu.constraint_name = tc.constraint_name AND kcu.table_name = tc.table_name
 98	            WHERE tc.table_name = ${table} AND tc.constraint_type = 'PRIMARY KEY'
 99	          ) pk ON pk.column_name = c.column_name
100	          WHERE c.table_name = ${table} AND c.table_schema = current_schema()
101	        `) as { name: string; notnull: number; pk: number }[]
102	        return rows.map(row => ({ name: row.name, notnull: Number(row.notnull), pk: Number(row.pk) }))
103	      }
104	      return (await sql.unsafe(`PRAGMA table_info(${table})`)) as { name: string; notnull: number; pk: number }[]
105	    },
106	    async controlVersions(table) {
107	      const rows = (await sql.unsafe(`SELECT version FROM ${table} ORDER BY version`)) as { version: number | string }[]
108	      return rows.map(row => Number(row.version))
109	    },
110	    async controlNames(table) {
111	      const rows = (await sql.unsafe(`SELECT version, name FROM ${table} ORDER BY version`)) as { version: number | string; name: string }[]
112	      return Object.fromEntries(rows.map(row => [Number(row.version), row.name]))
113	    },
114	    async seqLabels() {
115	      const rows = (await sql.unsafe(`SELECT label FROM seq ORDER BY id`)) as { label: string }[]
116	      return rows.map(row => row.label)
117	    },
118	    async runWithAdoptionProbe({ table, probeVersion, probeName, probeTable }) {
119	      const createProbeTable =
120	        dialect === 'postgres' ? `CREATE TABLE ${probeTable} (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY)` : `CREATE TABLE ${probeTable} (id INTEGER PRIMARY KEY)`
121	      const migrations: readonly AsyncMigration[] = [
122	        {
123	          version: probeVersion,
124	          name: probeName,
125	          statements: { sqlite: dialect === 'sqlite' ? [createProbeTable] : [], postgres: dialect === 'postgres' ? [createProbeTable] : [] },
126	          alreadyApplied: async probeSql => {
127	            if (dialect === 'postgres') {
128	              const [row] = (await probeSql.unsafe('SELECT to_regclass($1) IS NOT NULL AS found', [probeTable])) as { found: boolean }[]
129	              return Boolean(row?.found)
130	            }
131	            const rows = (await probeSql.unsafe(`SELECT name FROM sqlite_master WHERE type='table' AND name = $1`, [probeTable])) as { name: string }[]
132	            return rows.length > 0
133	          },
134	        },
135	      ]
136	      return runMigrations(sql, dialect, { table, migrations })
137	    },
138	    async createTableDirectly(tableName) {
139	      const ddl = dialect === 'postgres' ? `CREATE TABLE ${tableName} (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY)` : `CREATE TABLE ${tableName} (id INTEGER PRIMARY KEY)`
140	      await sql.unsafe(ddl)
141	    },
142	    async seedLegacyLedger(table, rows) {
143	      await sql.unsafe(LEGACY_LEDGER_DDL(table))
144	      for (const row of rows) await sql.unsafe(`INSERT INTO ${table} (version, applied_at) VALUES ($1, $2)`, [row.version, row.appliedAt])
145	    },
146	    async validateLedger(options) {
147	      await validateMigrationLedger(sql, dialect, options)
148	    },
149	  }
150	}
151	
152	defineMigrationRunnerContract({
153	  name: 'sync — bun:sqlite (runMigrationsSync)',
154	  async withEngine(body) {
155	    const db = new Database(':memory:')
156	    try {
157	      await body(syncSqliteEngine(db))
158	    } finally {
159	      db.close()
160	    }
161	  },
162	  async withConcurrentWriteLock(options, duringLock) {
163	    const dir = mkdtempSync(join(tmpdir(), 'thyrox-migrations-sync-'))
164	    const file = join(dir, 'db.sqlite')
165	    try {
166	      const db = new Database(file)
167	      try {
168	        runMigrationsSync(db, options)
169	        const holder = new Database(file)
170	        try {
171	          holder.run('BEGIN IMMEDIATE')
172	          await duringLock(syncSqliteEngine(db))
173	        } finally {
174	          holder.run('COMMIT')
175	          holder.close()
176	        }
177	      } finally {
178	        db.close()
179	      }
180	    } finally {
181	      rmSync(dir, { recursive: true, force: true })
182	    }
183	  },
184	})
185	
186	defineMigrationRunnerContract({
187	  name: 'async — sqlite vía Bun.SQL (runMigrations)',
188	  async withEngine(body) {
189	    const { sql } = openByUrl('sqlite://:memory:')
190	    try {
191	      await body(asyncEngine(sql, 'sqlite'))
192	    } finally {
193	      await sql.close()
194	    }
195	  },
196	  async withConcurrentWriteLock(options, duringLock) {
197	    const dir = mkdtempSync(join(tmpdir(), 'thyrox-migrations-async-sqlite-'))
198	    const file = join(dir, 'db.sqlite')
199	    try {
200	      const sql = new SQL(`sqlite://${file}`)
201	      try {
202	        await runMigrations(sql, 'sqlite', options)
203	        const holder = new Database(file)
204	        try {
205	          holder.run('BEGIN IMMEDIATE')
206	          await duringLock(asyncEngine(sql, 'sqlite'))
207	        } finally {
208	          holder.run('COMMIT')
209	          holder.close()
210	        }
211	      } finally {
212	        await sql.close()
213	      }
214	    } finally {
215	      rmSync(dir, { recursive: true, force: true })
216	    }
217	  },
218	})
219	
220	let postgresUrl: string | null = null
221	let postgresUrlError: Error | null = null
222	try {
223	  postgresUrl = resolvePostgresTestUrl(process.env)
224	} catch (e) {
225	  postgresUrlError = e instanceof Error ? e : new Error(String(e))
226	}
227	
228	if (postgresUrlError) {
229	  // La variable está declarada pero mal escrita: eso no es "no medido", es un
