 47	      const migrations: readonly SyncMigration[] = [
 48	        {
 49	          version: probeVersion,
 50	          name: probeName,
 51	          statements: { sqlite: [`CREATE TABLE ${probeTable} (id INTEGER PRIMARY KEY)`], postgres: [] },
 52	          alreadyApplied: probeDb => probeDb.query(`SELECT name FROM sqlite_master WHERE type='table' AND name = ?`).get(probeTable) !== null,
 53	        },
 54	      ]
 55	      return runMigrationsSync(db, { table, migrations })
 56	    },
 57	    async createTableDirectly(tableName) {
 58	      db.run(`CREATE TABLE ${tableName} (id INTEGER PRIMARY KEY)`)
 59	    },
 60	    async seedLegacyLedger(table, rows) {
 61	      db.run(LEGACY_LEDGER_DDL(table))
 62	      for (const row of rows) db.run(`INSERT INTO ${table} (version, applied_at) VALUES (?, ?)`, [row.version, row.appliedAt])
 63	    },
